function toggleWindowMode(flag) {
  // polarWindowButton.disabled = flag;
  polarWindowText.disabled = !flag;
  // polarLabelButton.disabled = !flag;
  _UIpolarPaneState.mode = flag ? MODE_WINDOW : MODE_LABEL;
}

["input", "change"].forEach(e => {
  polarWindowText.addEventListener(e, (event) => {
    let window = event.target.value;
    window = parseInt(window.replace(/\w\W/g, ""));
    _UIpolarPaneState.windowSec = window == NaN ? _UIpolarPaneState.windowSec : window * 60;
    mapplayer.updateTimeWindow(_UIpolarPaneState.startTs, _UIpolarPaneState.endTs);
  })
});

polarWindowText.addEventListener("focus", (event) => {
  mapplayer.updateTimeWindow(_UIpolarPaneState.startTs, _UIpolarPaneState.endTs);
});

polarWindowText.addEventListener("blur", (event) => {
  mapplayer.clearTimeWindow();
});

ctrlPolar.addEventListener("click", (event) => {
  setVisible(!getVisible());
});


function createAnnotationLabel(labelVal) {
  let l = document.createElement('div');
  l.className = 'polar-annotation-label-display';
  l.innerHTML = labelVal;
  l.style.display = labelVal == "" ? "none":"flex";
  return l;
}

document.getElementById('polarDotsToggle').addEventListener("click", (e) => {
  _UIpolarPaneState.showDotsOnPolar = !_UIpolarPaneState.showDotsOnPolar;
  _UIpolarPaneState.forceUpdate=true;
  updatePolarPane();
});


export function plotPolarMapOverlay(polar1, polar2, divId, halfPolar) {
    // Generate traces for both polars
    const traces1 = c.generatePolarTraces(polar1);
    const traces2 = c.generatePolarTraces(polar2);

    // Style traces2 with dotted lines and different color opacity
    traces2.forEach(trace => {
        trace.line = trace.line || {};
        trace.line.dash = 'dot';
        trace.opacity = 0.7;
        trace.name = (trace.name || '') + ' (overlay)';
    });

    // Find max R for axis scaling
    const rValues = [...traces1, ...traces2].map(trace => trace.r).flat();
    const maxR = Math.max(0, ...rValues);

    const sector = halfPolar ? [-90, 90] : [0, 360];
    const layout = {
        title: 'Polar Overlay Plot',
        polar: {
            sector: sector,
            radialaxis: {
                visible: true,
                title: 'Boat Speed (kn)',
                range: [0, maxR]
            },
            angularaxis: {
                direction: "clockwise",
                rotation: 90,
                tickmode: 'linear',
                tick0: 0,
                dtick: 10,
            }
        },
        showlegend: true,
        margin: {
            l: 10,
            r: 10,
            t: 20,
            b: 20
        }
    };
    const config = {
        displayModeBar: false,
        responsive: true
    };

    let allTraces = [...traces1, ...traces2];

    Plotly.newPlot(divId, allTraces, layout, config);
  }