// Lets overlays (e.g. weather pin picking) claim a map click before it falls through to
// the default play/pause toggle — each interceptor is tried in order and can return true to consume it.
let _clickInterceptors = [];
export function registerClickInterceptor(fn) {
    _clickInterceptors.push(fn);
}
export function unregisterClickInterceptor(fn) {
    _clickInterceptors = _clickInterceptors.filter(f => f !== fn);
}

