function resetAnimation() {
    if (!_animator) return;
    _animator.pause();
    _animator.reset();
    resetExtent();
}

function startAnimation() {
    if (!_animator) return;
    _animator.start();
    document.getElementById("map").focus();
}

function pauseAnimation() {
    if (!_animator) return;
    _animator.pause();
    document.getElementById("map").focus();
}

function toggleAnimationPlaying() {
    if (_mapUIState.isDisablePlayer) return;
    if (c.isUIState("TOOLS",c.UI_STATE.TOOLS.WAITING_FOR_USER_CLICK))
        return;

    if (c.isUIState("MAP", c.UI_STATE.MAP.PLAYING)) 
        pauseAnimation();
    else if (!c.isUIState("MAP",c.UI_STATE.MAP.PLAYING)) 
        startAnimation();
}

// Keyboard controls for pitch/tilt
document.addEventListener("keydown", function (event) {
    const activeElement = document.activeElement;
    const isInputField =
        activeElement.tagName === "INPUT" ||
        activeElement.tagName === "TEXTAREA" ||
        activeElement.isContentEditable;
    if (isInputField) return;

    switch (event.code) {
        case "Space":
            console.log("space pressed clicked");
            event.preventDefault();
            toggleAnimationPlaying();
            break;
        case "Comma":
            if (_animator) _animator.advanceFrame(-1);
            break;
        case "Period":
            if (_animator) _animator.advanceFrame(1);
            break;
        case "PageUp":
            event.preventDefault();
            const currentPitch = map.getPitch();
            map.setPitch(Math.min(currentPitch + 5, 85));
            console.log('Pitch:', map.getPitch());
            break;
        case "PageDown":
            event.preventDefault();
            const pitch = map.getPitch();
            map.setPitch(Math.max(pitch - 5, 0));
            console.log('Pitch:', map.getPitch());
            break;
    }
});

