function setTimeSkipRate(playSpeedSlider) {
    let playSpeed;
    if (playSpeedSlider) {
        playSpeed = skewedNormalize(parseFloat(playSpeedSlider), 1, 100);
        const timeSkipRate = playSpeed * (FASTEST_TIME_SKIP_RATE - SLOWEST_TIME_SKIP_RATE) + SLOWEST_TIME_SKIP_RATE;
        _animator.setTimeSkipRate(timeSkipRate);
    } else {
        const timeSkipRate = (_animator.lastTsSeconds - _animator.firstTsSeconds) / 120;
        _animator.setTimeSkipRate(timeSkipRate);
        playSpeed = inverseSkewedNormalize(timeSkipRate / FASTEST_TIME_SKIP_RATE * 100);
        slider.value = playSpeed;
    }
    console.log('Play speed changed to:', playSpeed * 100, "%, time skip rate of:" + _animator.timeSkipRate);
}

function updateProgressBar(progressBarPct) {
    const progressBar = document.getElementById("progressBar");
    progressBar.value = progressBarPct * 10;
    progressBar.disabled = false;

    const currentTimeDiv = document.getElementById("currentTime");
    currentTimeDiv.textContent = `${getCurrentPlayTime().format('YY-MM-DD HH:mm:ss')}`;

    const foundIdx = _race.sail().data.vessel.data.findIndex((f) => f.t.unix() > _animator.playTsSeconds);
    if (foundIdx > 0) {
        const f = _race.sail().data.vessel.data[foundIdx];
        document.getElementById("vesselSTW").innerHTML = f.bs;
        document.getElementById("vesselSOG").innerHTML = f.sog;
        document.getElementById("vesselVMG").innerHTML = f._vmg != undefined ? f._vmg.toFixed(2) : '';
        document.getElementById("vesselTWA").innerHTML = `${boatdata.convert360North0To180PosNeg(_race.sail().frameTwa(f))}°`;
        document.getElementById("vesselTWS").innerHTML = _race.sail().frameTws(f).toFixed(0);
        document.getElementById("vesselAWA").innerHTML = `${boatdata.convert360North0To180PosNeg(f.awa)}°`;
        document.getElementById("vesselAWS").innerHTML = f.aws.toFixed(0);
        document.getElementById("vesselTWD").innerHTML = `${_race.sail().frameTwd(f) != null ? _race.sail().frameTwd(f) : ''}°`;
        document.getElementById("vesselTH").innerHTML = `${f.th != null ? f.th : ''}°`;
        document.getElementById("vesselCOG").innerHTML = `${f.cog != undefined ? f.cog : f._cog}°`;
        document.getElementById("vesselPolar").innerHTML = `${f.calc?.polarPerf != undefined ? f.calc?.polarPerf : ''}%`;
        document.getElementById("vesselHeel").innerHTML = `${f.r != undefined ? f.r : ''}°`;
        const leewayAbs = _race.sail().getLeewayAbs(foundIdx);
        document.getElementById("vesselLeeway").innerHTML = `${leewayAbs != null ? leewayAbs : ''}°`;
    } else {
        document.getElementById("vesselSTW").innerHTML = "";
        document.getElementById("vesselSOG").innerHTML = "";
        document.getElementById("vesselVMG").innerHTML = "";
        document.getElementById("vesselTWA").innerHTML = "";
        document.getElementById("vesselTWS").innerHTML = "";
        document.getElementById("vesselAWA").innerHTML = "";
        document.getElementById("vesselAWS").innerHTML = "";
        document.getElementById("vesselTWD").innerHTML = "";
        document.getElementById("vesselTH").innerHTML = "";
        document.getElementById("vesselCOG").innerHTML = "";
        document.getElementById("vesselPolar").innerHTML = "";
        document.getElementById("vesselHeel").innerHTML = "";
        document.getElementById("vesselLeeway").innerHTML = "";
    }
}

