document.getElementById("progressBar").addEventListener("input", (event) => {
    const index = parseInt(event.target.value, 10);
    const progressBarRatio = index / 1000;
    setCurrentPlayTime((progressBarRatio * (_animator.lastTsSeconds - _animator.firstTsSeconds) + _animator.firstTsSeconds)*1000);
});

