export function clearTimeWindow() {
    updateTimeWindow(moment(0),moment(0));
}

export function updateTimeWindow(startTs, endTs) {
    const bar = document.getElementById('timeWindowBar');
    if (startTs != null && endTs != null && endTs.isAfter(startTs) && _animator) {
        const leftPercent = calcProgressBarPct(startTs / 1000);
        const widthPercent = calcProgressBarPct(endTs / 1000) - leftPercent;
        bar.style.left = leftPercent + '%';
        bar.style.width = widthPercent + '%';
    } else {
        bar.style.left = '0%';
        bar.style.width = '0%';
    }
}

function calcProgressBarPct(tsSeconds) {
    return ((tsSeconds - _animator.firstTsSeconds) / (_animator.lastTsSeconds - _animator.firstTsSeconds)) * 100;
}

export function displayTimeWindow(flag) {
    document.getElementById('timeWindowBar').style.display = flag ? "flex" : "none";
}

export function skewedNormalize(x, min = 1, max = 20, power = 3) {
    let t = (x - min) / (max - min);
    return Math.pow(t, power);
}

export function inverseSkewedNormalize(y, min = 1, max = 20, power = 3) {
    const t = Math.pow(y, 1 / power);
    return min + t * (max - min);
}
